import { createHash, randomUUID } from "node:crypto";
import { appendFileSync, existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { DIRS, ensureDirs, loadConfig } from "./config.ts";
import { logger } from "./logger.ts";

/**
 * Diagnostics vault: agent traces land in a tamper-evident, hash-chained
 * JSONL file under ~/.glint/diagnostics with 0600 perms. Records never leave
 * this machine — the most secure transport is no transport — and each record
 * carries the SHA-256 of the previous one, so any edit or deletion breaks the
 * chain and is detectable via verifyChain().
 */

const CHAIN_STATE = join(DIRS.diagnostics, ".chain");

export const SESSION_ID = randomUUID().slice(0, 8);

function tracePath(): string {
  const day = new Date().toISOString().slice(0, 10);
  return join(DIRS.diagnostics, `traces-${day}.jsonl`);
}

function lastHash(): string {
  try {
    return readFileSync(CHAIN_STATE, "utf8").trim() || "genesis";
  } catch {
    return "genesis";
  }
}

export function trace(type: string, payload: unknown): void {
  if (!loadConfig().diagnostics) return;
  try {
    ensureDirs();
    const prev = lastHash();
    const body = {
      ts: new Date().toISOString(),
      session: SESSION_ID,
      type,
      payload,
      prev,
    };
    const hash = createHash("sha256").update(JSON.stringify(body)).digest("hex");
    appendFileSync(tracePath(), JSON.stringify({ ...body, hash }) + "\n", { mode: 0o600 });
    writeFileSync(CHAIN_STATE, hash, { mode: 0o600 });
  } catch (err) {
    logger.warn("diagnostics.write_failed", String(err));
  }
}

export function verifyChain(path?: string): { ok: boolean; records: number; brokenAt?: number } {
  const file = path ?? tracePath();
  if (!existsSync(file)) return { ok: true, records: 0 };
  const lines = readFileSync(file, "utf8").split("\n").filter(Boolean);
  let count = 0;
  for (const line of lines) {
    try {
      const rec = JSON.parse(line);
      const { hash, ...body } = rec;
      const expect = createHash("sha256").update(JSON.stringify(body)).digest("hex");
      if (expect !== hash) return { ok: false, records: count, brokenAt: count + 1 };
      count++;
    } catch {
      return { ok: false, records: count, brokenAt: count + 1 };
    }
  }
  return { ok: true, records: count };
}

export function diagnosticsPath(): string {
  return tracePath();
}
